import{_ as r,I as t,c as s,o as d,j as e,ap as o,a as l,J as h}from"./chunks/framework.BVMg0REN.js";const P=JSON.parse('{"title":"进阶功能说明","description":"","frontmatter":{},"headers":[],"relativePath":"Features/AdvancedTasks.md","filePath":"zh/Features/AdvancedTasks.md","lastUpdated":1787668996000}'),n={name:"Features/AdvancedTasks.md"},c={id:"进阶功能说明",tabindex:"-1"};function b(k,a,u,m,p,f){const i=t("Badge");return d(),s("div",null,[e("h1",c,[a[0]||(a[0]=l("进阶功能说明")),h(i,{type:"warning",text:"普通"}),a[1]||(a[1]=l()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#进阶功能说明","aria-label":"Permalink to “进阶功能说明”"},"​",-1))]),a[3]||(a[3]=o('<div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>本文整理循环刷取、自动战斗、抄作业、多开等更偏进阶使用的功能说明。</p></div><h2 id="一、心纸营建与历险" tabindex="-1">一、心纸营建与历险 <a class="header-anchor" href="#一、心纸营建与历险" aria-label="Permalink to “一、心纸营建与历险”">​</a></h2><h3 id="心纸营建" tabindex="-1">心纸营建 <a class="header-anchor" href="#心纸营建" aria-label="Permalink to “心纸营建”">​</a></h3><ul><li>单次执行版。</li><li>支持自动派遣。</li><li>可选线路材料、难度 <code>1-5</code>、派遣次数 <code>1-4</code>、是否打造家具。</li></ul><h3 id="家具历险首通" tabindex="-1">家具历险首通 <a class="header-anchor" href="#家具历险首通" aria-label="Permalink to “家具历险首通”">​</a></h3><ul><li>可循环执行。</li><li>适合首通或临时刷佛脚。</li><li>建议先手动选好密探并在历险内配过一次队。</li></ul><h2 id="二、自动刷神秘洞窟" tabindex="-1">二、自动刷神秘洞窟 <a class="header-anchor" href="#二、自动刷神秘洞窟" aria-label="Permalink to “二、自动刷神秘洞窟”">​</a></h2><ul><li>循环任务。</li><li>支持游戏内置自动战斗或抄作业两种方式。</li><li>可指定队伍。</li><li>若使用抄作业，需要在对应洞窟入口处开始任务。</li></ul><h2 id="三、主线与成就刷取" tabindex="-1">三、主线与成就刷取 <a class="header-anchor" href="#三、主线与成就刷取" aria-label="Permalink to “三、主线与成就刷取”">​</a></h2><h3 id="_6-24-7-15" tabindex="-1"><code>6-24 / 7-15</code> <a class="header-anchor" href="#_6-24-7-15" aria-label="Permalink to “6-24 / 7-15”">​</a></h3><ul><li>可刷到体力耗尽。</li><li>不会消耗白金币购买体力。</li><li>也有“指定循环次数”版本。</li></ul><h3 id="三千世界刷成就" tabindex="-1">三千世界刷成就 <a class="header-anchor" href="#三千世界刷成就" aria-label="Permalink to “三千世界刷成就”">​</a></h3><ul><li>在宇宙匣 <code>三千世界</code> 的目标关卡内开始任务。</li><li>主要用于刷共同出战类成就。</li></ul><h2 id="四、自动抄作业-v3" tabindex="-1">四、自动抄作业 V3 <a class="header-anchor" href="#四、自动抄作业-v3" aria-label="Permalink to “四、自动抄作业 V3”">​</a></h2><h3 id="基础前提" tabindex="-1">基础前提 <a class="header-anchor" href="#基础前提" aria-label="Permalink to “基础前提”">​</a></h3><ol><li>已导入作业并完成激活。</li><li>已按作业需求调整队伍和命盘。</li><li>游戏内右侧“自动 / 手动 / 倍速”面板保持展开。</li></ol><h3 id="开始位置" tabindex="-1">开始位置 <a class="header-anchor" href="#开始位置" aria-label="Permalink to “开始位置”">​</a></h3><ul><li>未勾选“战斗中开始抄作业”：在“开始战斗”界面开始。</li><li>勾选后：在战斗内右上角能看到“回合 X”时开始。</li></ul><h3 id="特殊适配任务" tabindex="-1">特殊适配任务 <a class="header-anchor" href="#特殊适配任务" aria-label="Permalink to “特殊适配任务”">​</a></h3><ul><li>部分任务会自动循环。</li><li>若作业设置为“点左上角重开”，可自动导航下一把。</li><li>目前提到支持主线、洞窟、兰台、地宫遗迹等场景。</li></ul><h2 id="五、录制作业" tabindex="-1">五、录制作业 <a class="header-anchor" href="#五、录制作业" aria-label="Permalink to “五、录制作业”">​</a></h2><p><code>v2.0.0-beta.3</code> 及以上新增录制作业功能（仍处测试阶段）：</p><ol><li>在录制作业界面点击“开始录制”。</li><li>通过“操作记录仪”悬浮窗记录操作。</li><li>尽量不要直接去点模拟器本体，避免记录异常。</li></ol><h2 id="六、多开操作提示" tabindex="-1">六、多开操作提示 <a class="header-anchor" href="#六、多开操作提示" aria-label="Permalink to “六、多开操作提示”">​</a></h2><h3 id="复制模拟器与端口获取" tabindex="-1">复制模拟器与端口获取 <a class="header-anchor" href="#复制模拟器与端口获取" aria-label="Permalink to “复制模拟器与端口获取”">​</a></h3><ul><li><code>MuMu</code>：通过多开管理器复制已有模拟器或新建安卓 12 模拟器。</li><li><code>BlueStacks</code>：通过多开管理器创建新实例。</li><li><code>雷电</code>：通过多开管理器复制已有实例。</li></ul><h3 id="获取端口的方法" tabindex="-1">获取端口的方法 <a class="header-anchor" href="#获取端口的方法" aria-label="Permalink to “获取端口的方法”">​</a></h3><ol><li>直接在模拟器设置或多开器中查看。</li><li>或在 <code>ADB</code> 目录执行：</li></ol><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devices</span></span></code></pre></div><ol start="3"><li>输出中的 <code>127.0.0.1:&lt;端口&gt;</code> 或 <code>emulator-&lt;四位数字&gt;</code> 即为连接地址。</li></ol><h2 id="七、适合什么时候使用这些功能" tabindex="-1">七、适合什么时候使用这些功能 <a class="header-anchor" href="#七、适合什么时候使用这些功能" aria-label="Permalink to “七、适合什么时候使用这些功能”">​</a></h2><ul><li>要长时间挂日常：优先循环任务</li><li>要刷洞窟或打活动：先看 <a href="./../Activity/Current.html">当前活动</a></li><li>要复现问题：优先保留日志并查看 <a href="./../FAQ/01-general-issues.html">FAQ</a></li></ul>',32))])}const _=r(n,[["render",b]]);export{P as __pageData,_ as default};
